# homopolymers
import re
for m in re.finditer(r'(A{5,}|T{5,}|G{5,}|C{5,})', seq):
    print("homopolymer", m.start()+1, m.group(), len(m.group()))

# tandem repeats: find repeated k-mers
def tandem(s, k, mincopies=3):
    out=[]
    i=0
    while i < len(s)-k*mincopies+1:
        unit=s[i:i+k]
        cnt=1
        j=i+k
        while s[j:j+k]==unit:
            cnt+=1; j+=k
        if cnt>=mincopies:
            out.append((i+1,unit,cnt))
            i=j
        else:
            i+=1
    return out
for k in (2,3,4,5,6):
    t=tandem(seq,k,3)
    if t: print("k=%d"%k, t[:20])
