seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip()
n=len(seq)
comp={"A":"T","T":"A","G":"C","C":"G"}
def rc(s): return "".join(comp[b] for b in reversed(s))

# inverted repeats (palindromes): find s[i:i+L] whose revcomp appears nearby
best=[]
for L in range(8, 30):
    seen={}
    for i in range(n-L+1):
        k=seq[i:i+L]
        seen.setdefault(k,[]).append(i)
    # find k and its rc both present with gap
    for k,pos in seen.items():
        r=rc(k)
        if r in seen and r!=k:
            for i in pos:
                for j in seen[r]:
                    if j>i+L:
                        gap=j-(i+L)
                        best.append((gap, L, i+1, j+L, k, r))
best.sort()
print("closest inverted repeats (gap, len, start1, end2):")
for b in best[:15]:
    print(b[0], b[1], b[2], b[3], b[4], "<->", b[5])
